export function AuditLog({
  caption = "{{caption}}",
  rows = "{{rows}}",
  accent = "{{accent}}",
  monospaceIds = {{monospaceIds}},
  striped = {{striped}},
}) {
  const data = [
    { actor: "A. Whitfield", actorId: "usr_8841", action: "role.updated", target: "acct_2210", time: "2026-08-18T08:12:00Z", label: "18 Aug, 08:12" },
    { actor: "M. Duarte", actorId: "usr_1190", action: "login.failed", target: "usr_1190", time: "2026-08-18T07:58:00Z", label: "18 Aug, 07:58" },
    { actor: "S. Novak", actorId: "usr_4402", action: "record.deleted", target: "rec_7734", time: "2026-08-17T22:41:00Z", label: "17 Aug, 22:41" },
    { actor: "A. Whitfield", actorId: "usr_8841", action: "permission.granted", target: "team_09", time: "2026-08-17T19:05:00Z", label: "17 Aug, 19:05" },
    { actor: "J. Kocher", actorId: "usr_2255", action: "export.completed", target: "rpt_5561", time: "2026-08-17T14:30:00Z", label: "17 Aug, 14:30" },
  ].slice(0, Number(rows));
  const mono = monospaceIds ? { fontFamily: "SFMono-Regular, Consolas, monospace" } : {};
  return (
    <table style={{ borderCollapse: "collapse", width: "100%", maxWidth: 520, fontFamily: "system-ui, sans-serif", fontSize: 13, color: "#241430", background: "#FAF7F2" }}>
      <caption style={{ textAlign: "left", fontWeight: 600, paddingBottom: 8 }}>{caption}</caption>
      <thead>
        <tr style={{ background: accent, color: "#FAF7F2" }}>
          {["Actor", "Action", "Target", "Timestamp"].map((h) => (
            <th key={h} scope="col" style={{ textAlign: "left", fontWeight: 600, padding: "10px 12px" }}>{h}</th>
          ))}
        </tr>
      </thead>
      <tbody>
        {data.map((row, i) => (
          <tr key={row.time} style={{ background: striped && i % 2 === 1 ? "#24143010" : "transparent", borderBottom: "1px solid #24143020" }}>
            <th scope="row" style={{ textAlign: "left", fontWeight: 600, padding: "10px 12px" }}>
              {row.actor}
              <span style={{ display: "block", fontSize: 11, fontWeight: 400, color: "#24143099", ...mono }}>{row.actorId}</span>
            </th>
            <td style={{ padding: "10px 12px" }}>{row.action}</td>
            <td style={{ padding: "10px 12px", fontSize: monospaceIds ? 12.5 : 13, ...mono }}>{row.target}</td>
            <td style={{ padding: "10px 12px" }}><time dateTime={row.time}>{row.label}</time></td>
          </tr>
        ))}
      </tbody>
    </table>
  );
}
